PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?zlabel ?sp ?sptype
WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zlabel }
  OPTIONAL { ?zone brick:hasSetpoint ?sp . OPTIONAL { ?sp brick:hasSubclass ?sptype } }
  FILTER(str(?zone) || str(?zlabel) LIKE "%Core_mid%" || str(?zlabel) LIKE "%Core%" )
}

